class LeoOperatorKeyTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void alphaEquivalentJoinSurfacesHaveSameStructuralKey() {
		Join first = new Join(
				pattern("a", "urn:knows", "b"),
				pattern("b", "urn:knows", "c"));
		Join second = new Join(
				pattern("x", "urn:knows", "y"),
				pattern("y", "urn:knows", "z"));

		assertEquals(LeoOperatorKey.from(first), LeoOperatorKey.from(second));
	}

	@Test
	void inputBindingShapeIsAlphaNormalizedAndPositionSensitive() {
		StatementPattern first = pattern("a", "urn:knows", "b");
		StatementPattern renamed = pattern("x", "urn:knows", "y");

		assertEquals(LeoOperatorKey.alphaNormalizedInputBindingShape(first, Set.of("a")),
				LeoOperatorKey.alphaNormalizedInputBindingShape(renamed, Set.of("x")));
		assertNotEquals(LeoOperatorKey.alphaNormalizedInputBindingShape(first, Set.of("a")),
				LeoOperatorKey.alphaNormalizedInputBindingShape(first, Set.of("b")));
		assertEquals("unbound", LeoOperatorKey.alphaNormalizedInputBindingShape(first, Set.of()));
		assertEquals("unbound", LeoOperatorKey.alphaNormalizedInputBindingShape(first, Set.of("irrelevant")));
	}

	@Test
	void canonicalJoinSurfaceMatchesExhaustiveReference() {
		List<StatementPattern> factors = List.of(
				pattern("a", "urn:follows", "b"),
				pattern("b", "urn:follows", "c"),
				pattern("c", "urn:follows", "d"),
				pattern("d", "urn:follows", "a"),
				pattern("a", "urn:name", "name"),
				pattern("name", "urn:language", "language"));
		String expected = "JOIN|factors=" + exhaustiveStatementJoinSurface(factors);

		assertEquals(expected, LeoOperatorKey.from(join(factors, 0, 1, 2, 3, 4, 5)).structuralFingerprint());
		assertEquals(expected, LeoOperatorKey.from(join(factors, 5, 3, 1, 4, 2, 0)).structuralFingerprint());
		assertEquals(expected, LeoOperatorKey.from(join(factors, 2, 4, 0, 5, 3, 1)).structuralFingerprint());
	}

	@Test
	void differentConstantsChangeTheStructuralKey() {
		Join knows = new Join(
				pattern("a", "urn:knows", "b"),
				pattern("b", "urn:knows", "c"));
		Join likes = new Join(
				pattern("a", "urn:likes", "b"),
				pattern("b", "urn:knows", "c"));

		assertNotEquals(LeoOperatorKey.from(knows), LeoOperatorKey.from(likes));
	}

	@Test
	void differentJoinConnectivityChangesTheStructuralKey() {
		Join connected = new Join(
				pattern("a", "urn:knows", "b"),
				pattern("b", "urn:knows", "c"));
		Join disconnected = new Join(
				pattern("a", "urn:knows", "b"),
				pattern("c", "urn:knows", "d"));

		assertNotEquals(LeoOperatorKey.from(connected), LeoOperatorKey.from(disconnected));
	}

	@Test
	void valuesKeyPreservesArityAndDuplicateMultiplicity() {
		BindingSetAssignment unaryDuplicate = values(List.of(row("x", "urn:1"), row("x", "urn:1")));
		BindingSetAssignment unaryFreshObjects = values(List.of(row("x", "urn:1"), row("x", "urn:1")));
		BindingSetAssignment unarySingle = values(List.of(row("x", "urn:1")));
		BindingSetAssignment binarySingle = values(List.of(row("x", "urn:1", "y", "urn:2")));

		assertEquals(LeoOperatorKey.from(unaryDuplicate), LeoOperatorKey.from(unaryFreshObjects));
		assertNotEquals(LeoOperatorKey.from(unaryDuplicate), LeoOperatorKey.from(unarySingle));
		assertNotEquals(LeoOperatorKey.from(unarySingle), LeoOperatorKey.from(binarySingle));
	}

	@Test
	void unionBranchOrderDoesNotAffectKey() {
		StatementPattern left = pattern("s", "urn:left", "o");
		StatementPattern right = pattern("o", "urn:right", "label");

		assertEquals(LeoOperatorKey.from(new Union(left, right)),
				LeoOperatorKey.from(new Union(right.clone(), left.clone())));
	}

	@Test
	void differenceLeftRightOrderIsSignificant() {
		StatementPattern left = pattern("s", "urn:left", "o");
		StatementPattern right = pattern("o", "urn:right", "label");

		assertNotEquals(LeoOperatorKey.from(new Difference(left, right)),
				LeoOperatorKey.from(new Difference(right.clone(), left.clone())));
	}

	@Test
	void statementPatternScopeChangesTheStructuralKey() {
		StatementPattern defaultScope = new StatementPattern(StatementPattern.Scope.DEFAULT_CONTEXTS,
				new Var("s"), new Var("predicate", VF.createIRI("urn:knows")), new Var("o"));
		StatementPattern namedScope = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				new Var("s"), new Var("predicate", VF.createIRI("urn:knows")), new Var("o"));

		assertNotEquals(LeoOperatorKey.from(defaultScope), LeoOperatorKey.from(namedScope));
	}

	@Test
	void differentFilterComparisonsDoNotCollide() {
		Filter equalsFilter = new Filter(pattern("s", "urn:knows", "o"),
				new Compare(new Var("o"), new ValueConstant(VF.createLiteral(10)), Compare.CompareOp.EQ));
		Filter lessThanFilter = new Filter(pattern("s", "urn:knows", "o"),
				new Compare(new Var("o"), new ValueConstant(VF.createLiteral(10)), Compare.CompareOp.LT));

		assertNotEquals(LeoOperatorKey.from(equalsFilter), LeoOperatorKey.from(lessThanFilter));
	}

	@Test
	void predicateContextModeAbstractsNonPredicateConstantsButKeepsPredicates() {
		Join firstSubject = new Join(
				constantSubjectPattern("urn:alice", "urn:knows", "b"),
				pattern("b", "urn:knows", "c"));
		Join secondSubject = new Join(
				constantSubjectPattern("urn:bob", "urn:knows", "b"),
				pattern("b", "urn:knows", "c"));
		Join differentPredicate = new Join(
				constantSubjectPattern("urn:bob", "urn:likes", "b"),
				pattern("b", "urn:knows", "c"));

		assertNotEquals(LeoOperatorKey.from(firstSubject), LeoOperatorKey.from(secondSubject));
		assertEquals(LeoOperatorKey.from(firstSubject, "",
				LeoOperatorKey.ConstantMode.PREDICATE_AND_CONTEXT_EXACT),
				LeoOperatorKey.from(secondSubject, "",
						LeoOperatorKey.ConstantMode.PREDICATE_AND_CONTEXT_EXACT));
		assertNotEquals(LeoOperatorKey.from(secondSubject, "",
				LeoOperatorKey.ConstantMode.PREDICATE_AND_CONTEXT_EXACT),
				LeoOperatorKey.from(differentPredicate, "",
						LeoOperatorKey.ConstantMode.PREDICATE_AND_CONTEXT_EXACT));
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(new Var(subject), new Var("predicate", VF.createIRI(predicate)), new Var(object));
	}

	private static StatementPattern constantSubjectPattern(String subject, String predicate, String object) {
		return new StatementPattern(new Var("subject", VF.createIRI(subject)),
				new Var("predicate", VF.createIRI(predicate)), new Var(object));
	}

	private static TupleExpr join(List<StatementPattern> factors, int... order) {
		TupleExpr result = factors.get(order[0]).clone();
		for (int ordinal = 1; ordinal < order.length; ordinal++) {
			result = new Join(result, factors.get(order[ordinal]).clone());
		}
		return result;
	}

	private static String exhaustiveStatementJoinSurface(List<StatementPattern> factors) {
		int[] order = new int[factors.size()];
		for (int ordinal = 0; ordinal < order.length; ordinal++) {
			order[ordinal] = ordinal;
		}
		String[] minimum = new String[1];
		exhaustiveStatementJoinSurface(factors, order, 0, minimum);
		return minimum[0];
	}

	private static void exhaustiveStatementJoinSurface(List<StatementPattern> factors, int[] order, int offset,
			String[] minimum) {
		if (offset == order.length) {
			Map<String, Integer> variableOrdinals = new HashMap<>();
			List<String> keys = new ArrayList<>(order.length);
			for (int factorOrdinal : order) {
				StatementPattern factor = factors.get(factorOrdinal);
				keys.add("SP|patternScope=" + factor.getScope()
						+ "|s=" + referenceVarKey(factor.getSubjectVar(), variableOrdinals)
						+ "|p=" + referenceVarKey(factor.getPredicateVar(), variableOrdinals)
						+ "|o=" + referenceVarKey(factor.getObjectVar(), variableOrdinals)
						+ "|c=" + referenceVarKey(factor.getContextVar(), variableOrdinals));
			}
			String candidate = String.join(";", keys);
			if (minimum[0] == null || candidate.compareTo(minimum[0]) < 0) {
				minimum[0] = candidate;
			}
			return;
		}
		for (int index = offset; index < order.length; index++) {
			swap(order, offset, index);
			exhaustiveStatementJoinSurface(factors, order, offset + 1, minimum);
			swap(order, offset, index);
		}
	}

	private static String referenceVarKey(Var var, Map<String, Integer> variableOrdinals) {
		if (var == null) {
			return "<null>";
		}
		if (var.hasValue()) {
			return "const:iri:" + var.getValue().stringValue();
		}
		return "v" + variableOrdinals.computeIfAbsent(var.getName(), ignored -> variableOrdinals.size());
	}

	private static void swap(int[] values, int left, int right) {
		int value = values[left];
		values[left] = values[right];
		values[right] = value;
	}

	private static BindingSetAssignment values(List<? extends BindingSet> rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(new ArrayList<>(rows));
		return assignment;
	}

	private static MapBindingSet row(String name, String value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, VF.createIRI(value));
		return row;
	}

	private static MapBindingSet row(String firstName, String firstValue, String secondName, String secondValue) {
		MapBindingSet row = row(firstName, firstValue);
		row.addBinding(secondName, VF.createIRI(secondValue));
		return row;
	}
}
